#include <iostream>
using namespace std;

class Point {
    int x_, y_;

public:
    Point() : x_(0), y_(0) {}
    Point(int x, int y) : x_(x), y_(y) {}
    void show() const { cout << x_ << "," << y_ << endl; }
};

int main() {
    Point origin;
    Point p(3, 4);
    origin.show();
    p.show();
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Pet {
    string name_;
    int age_;

public:
    Pet(string name = "Unknown", int age = 1) : name_(name), age_(age) {}
    void show() const { cout << name_ << " " << age_ << endl; }
};

int main() {
    Pet a;
    Pet b("Moti");
    Pet c("Kali", 4);
    a.show();
    b.show();
    c.show();
    return 0;
}

